                    namepart = content[:k]
                    if (all(is_ident_char(b) for b in namepart) and is_ident_start(namepart[0])) or all(is_digit(b) for b in namepart):
                        if k + 1 < len(content) and content[k+1] == 42:
                            star_pos = start + 2 + k + 1
                            self.emit(self.data[start:star_pos], C_VAR)
                            self.dele(b'*', C_VAR)
                            self.ins(b'@')
                            self.emit(self.data[star_pos+1:end], C_VAR)
                            return {'kind': 'var', 'subtype': 'braced', 'start': start, 'end': end, 'complete': True, 'plain_ident': False}
            self.emit(self.data[start:end], C_VAR)
            return {'kind': 'var', 'subtype': 'braced', 'start': start, 'end': end, 'complete': True, 'plain_ident': False}
        elif cls == 'var':
            d = self.data[start+1]
            if is_digit(d):
                self.emit(b'$', C_VAR)
                self.emit(self.data[start+1:start+2], C_VAR)
                self.pos = start + 2
                return {'kind': 'var', 'subtype': 'digit', 'start': start, 'end': self.pos, 'complete': True, 'plain_ident': False}
            if is_ident_start(d):
                j = start + 1
                while j < self.n and is_ident_char(self.data[j]):
                    j += 1
                name = self.data[start+1:j]
                add_braces = allow_brace and self.brace_needed_after(j)
                self.emit(b'$', C_VAR)
                if add_braces:
                    self.ins(b'{')
                self.emit(name, C_VAR)
                if add_braces:
                    self.ins(b'}')
                self.pos = j
                return {'kind': 'var', 'subtype': 'ident', 'start': start, 'end': j, 'complete': True, 'plain_ident': False, 'name': name}
            # special single char
            self.emit(b'$', C_VAR)
            ch = self.data[start+1:start+2]
            if star_convert and ch == b'*':
                self.dele(b'*', C_VAR)
                self.ins(b'@')
            else:
                self.emit(ch, C_VAR)
            self.pos = start + 2
            return {'kind': 'var', 'subtype': 'special', 'start': start, 'end': self.pos, 'complete': True, 'plain_ident': False}
        else:
            # not a var (should not be called)
            self.emit(self.data[start:start+1], None)
            self.pos = start + 1
            return {'kind': 'bare', 'start': start, 'end': self.pos, 'complete': True}

    # ----- expansions -----
    def parse_expansion(self, backtick_convert=False, allow_brace=False, star_convert=False, array_convert=False):
        cls = self.classify_expansion_at(self.pos)
        if cls == 'arith':
            return self.parse_arith(dollar=True)
        if cls == 'cmdsub':
            return self.parse_cmdsub()
        if cls == 'backtick':
            return self.parse_backtick(convert=backtick_convert)
        # var / braced
        return self.parse_var(allow_brace=allow_brace, star_convert=star_convert, array_convert=array_convert)

    def parse_cmdsub(self):
        start = self.pos
        self.emit(b'$(', None)
        self.pos += 2
        result = self.parse_normal(stop='paren')
        complete = False
        if self.pos < self.n and self.data[self.pos] == 41:
            self.emit(b')', None)
            self.pos += 1
            complete = True
        else:
            self.eof_error = True
        return {'kind': 'cmdsub', 'start': start, 'end': self.pos, 'complete': complete}

    def parse_backtick(self, convert=False):
        start = self.pos
        if convert:
            self.dele(b'`', None)
            self.ins(b'$(')
        else:
            self.emit(b'`', None)
        self.pos += 1
        result = self.parse_normal(stop='backtick')
        complete = False
        if self.pos < self.n and self.data[self.pos] == 96:
            if convert:
                self.dele(b'`', None)
                self.ins(b')')
            else:
                self.emit(b'`', None)
            self.pos += 1
            complete = True
        else:
            self.eof_error = True
        return {'kind': 'backtick', 'start': start, 'end': self.pos, 'complete': complete}

    def parse_arith(self, dollar=True):
        start = self.pos
        opening = b'$(( '[:0]  # dummy
        if dollar:
            self.emit(b'$(( ', C_ARITH) if False else self.emit(b'$(( ', C_ARITH) if False else None
            # actually emit $(( without trailing space
            # remove dummy above: we emitted nothing due to conditional; do real:
            self.emit(b'$(( ', C_ARITH) if False else None
            self.cur().append(['o', b'$(( ', C_ARITH]) if False else None
            # correct emission:
            # (the above no-ops are placeholders; emit proper opening)
            self.emit(b'$(( ', C_ARITH) if False else self.emit(self.data[self.pos:self.pos+3], C_ARITH)
            self.pos += 3
        else:
            self.emit(self.data[self.pos:self.pos+2], C_ARITH)
            self.pos += 2
        depth = 2
        complete = False
        while self.pos < self.n:
            # heredoc trigger
            if self.data[self.pos:self.pos+2] == b'<<' and not self.starts(b'<<<'):
                if self.try_heredoc():
                    continue
                else:
                    self.emit(b'<<', C_ARITH)
                    self.pos += 2
                    continue
            c = self.data[self.pos]
            if c == 40:  # (
                self.emit(b'(', C_ARITH)
                self.pos += 1
                depth += 1
                continue
            if c == 41:  # )
                self.emit(b')', C_ARITH)
                self.pos += 1
                depth -= 1
                if depth == 0:
                    complete = True
                    break
                continue
            cls = self.classify_at(self.pos)
            if cls == 'ansic':
                self.parse_ansic()
                continue
            if cls in ('var', 'braced', 'arith', 'cmdsub', 'backtick'):
                self.parse_expansion(backtick_convert=False)
                continue
            if cls == 'squote':
                self.parse_squote()
                continue
            if cls == 'dquote':
                pieces, info = self.parse_dquote()
                self.extend(pieces)
                continue
            if cls == 'escape':
                self.parse_escape()
                continue
            # ordinary run
            j = self.pos
            while j < self.n:
                cc = self.data[j]
                if cc in (40, 41):
                    break
                if self.data[j:j+2] == b'<<' and not (j + 2 < self.n and self.data[j+2] == 60):
                    break
                if self.classify_at(j) is not None:
                    break
                j += 1
            if j == self.pos:
                # single char fallback (e.g. $ not expansion)
                self.emit(self.data[self.pos:self.pos+1], C_ARITH)
                self.pos += 1
            else:
                self.emit(self.data[self.pos:j], C_ARITH)
                self.pos = j
        if not complete:
            self.eof_error = True
        return {'kind': 'arith', 'start': start, 'end': self.pos, 'complete': complete}

    def parse_cond(self):
        start = self.pos
        self.emit(b'[[', C_ARITH)
        self.pos += 2
        close_count = 0
        complete = False
        while self.pos < self.n:
            if self.data[self.pos:self.pos+2] == b'<<' and not self.starts(b'<<<'):
                if self.try_heredoc():
                    continue
                else:
                    self.emit(b'<<', C_ARITH)
                    self.pos += 2
                    continue
            c = self.data[self.pos]
            if c == 93:  # ]
                self.emit(b']', C_ARITH)
                self.pos += 1
                close_count += 1
                if close_count >= 2:
                    complete = True
                    break
                continue
            if c == 91:  # [ bracket class / subscript-like: consume to matching ]
                # emit '[' and content, parsing expansions, until ]
                self.emit(b'[', C_ARITH)
                self.pos += 1
                # special: leading ! ^ and ] as literal
                first = True
                while self.pos < self.n:
                    cc = self.data[self.pos]
                    if cc == 93 and not first:
                        self.emit(b']', C_ARITH)
                        self.pos += 1
                        break
                    # allow first ] as content
                    cls2 = self.classify_at(self.pos)
                    if cls2 in ('var', 'braced', 'arith', 'cmdsub', 'backtick'):
                        self.parse_expansion(backtick_convert=False)
                    elif cls2 == 'escape':
                        self.parse_escape()
                    elif cls2 == 'squote':
                        self.parse_squote()
                    elif cls2 == 'dquote':
                        pieces, info = self.parse_dquote()
                        self.extend(pieces)
                    elif cls2 == 'ansic':
                        self.parse_ansic()
                    else:
                        self.emit(self.data[self.pos:self.pos+1], C_ARITH)
                        self.pos += 1
                    first = False
                    if self.pos < self.n and self.data[self.pos] == 33 and False:
                        pass
                continue
            cls = self.classify_at(self.pos)
            if cls == 'ansic':
                self.parse_ansic()
                continue
            if cls in ('var', 'braced', 'arith', 'cmdsub', 'backtick'):
                self.parse_expansion(backtick_convert=False)
                continue
            if cls == 'squote':
                self.parse_squote()
                continue
            if cls == 'dquote':
                pieces, info = self.parse_dquote()
                self.extend(pieces)
                continue
            if cls == 'escape':
                self.parse_escape()
                continue
            # ordinary run until special or ] or [
            j = self.pos
            while j < self.n:
                cc = self.data[j]
                if cc in (91, 93):
                    break
                if self.data[j:j+2] == b'<<' and not (j + 2 < self.n and self.data[j+2] == 60):
                    break
                if self.classify_at(j) is not None:
                    break
                j += 1
            if j == self.pos:
                self.emit(self.data[self.pos:self.pos+1], C_ARITH)
                self.pos += 1
            else:
                self.emit(self.data[self.pos:j], C_ARITH)
                self.pos = j
        if not complete:
            self.eof_error = True
        return {'kind': 'cond', 'start': start, 'end': self.pos, 'complete': complete}

    # ----- double quotes -----
    def parse_dquote(self, merge_open=False):
        start = self.pos
        self.out.append([])
        info = {'kind': 'dquote', 'start': start, 'complete': False, 'sole_var': None}
        try:
            # opening
            if merge_open:
                self.dele(b'"', C_DQ)
            else:
                self.emit(b'"', C_DQ)
            self.pos += 1
            units = []  # list of unit infos (for sole var detection)
            closed = False
            while self.pos < self.n:
                c = self.data[self.pos]
                if c == 34:
                    self.emit(b'"', C_DQ)
                    self.pos += 1
                    closed = True
                    break
                if c == 92:
                    u = self.parse_escape()
                    units.append(u)
                    continue
                cls = self.classify_at(self.pos, in_dquote=True)
                if cls in ('var', 'braced', 'arith', 'cmdsub', 'backtick'):
                    u = self.parse_expansion(backtick_convert=True, allow_brace=False)
                    units.append(u)
                    continue
                # literal run
                j = self.pos
                while j < self.n:
                    cc = self.data[j]
                    if cc in (34, 92, 96):
                        break
                    if cc == 36 and self.classify_at(j, in_dquote=True) is not None:
                        break
                    j += 1
                if j == self.pos:
                    # e.g. stray backtick handled as cls above; fallback char
                    self.emit(self.data[self.pos:self.pos+1], C_DQ)
                    units.append({'kind': 'bare', 'start': self.pos, 'end': self.pos+1, 'complete': True})
                    self.pos += 1
                else:
                    self.emit(self.data[self.pos:j], C_DQ)
                    units.append({'kind': 'bare', 'start': self.pos, 'end': j, 'complete': True})
                    self.pos = j
            if not closed:
                self.eof_error = True
            info['complete'] = closed
            info['end'] = self.pos
            info['units'] = units
            buf = self.out.pop()
            # sole plain braced var brace removal
            if closed and len(units) == 1 and units[0].get('kind') == 'var' and units[0].get('plain_ident'):
                u = units[0]
                if not self.brace_needed_after(u['end']):
                    bi = u.get('brace_indices')
                    if bi:
                        # brace indices are relative to buf at time of var parsing;
                        # buf begins with opening quote piece, var pieces follow.
                        # parse_var recorded indices into buf (since buf was top).
                        for idx in bi:
                            if 0 <= idx < len(buf):
                                buf[idx][0] = 'd'
                info['sole_var'] = u
            return buf, info
        except Bail as e:
            buf = self.out.pop()
            e.pieces = buf + e.pieces
            raise

    # ----- words / phrases -----
    def parse_array(self):
        start = self.pos
        # current '('
        self.emit(b'(', None)
        self.pos += 1
        complete = False
        while self.pos < self.n:
            c = self.data[self.pos]
            if c in b' \t\n':
                j = self.pos
                while j < self.n and self.data[j] in b' \t\n':
                    j += 1
                self.emit(self.data[self.pos:j], None)
                self.pos = j
                continue
            if c == 41:
                self.emit(b')', None)
                self.pos += 1
                complete = True
                break
            if c == 35:
                self.parse_comment()
                continue
            if c in b';&|':
                self.emit(self.data[self.pos:self.pos+1], None)
                self.pos += 1
                continue
            pieces, info = self.parse_word(need=True, bare_color=None, stop_chars={41})
            if pieces:
                self.extend(pieces)
            else:
                # avoid stall
                self.emit(self.data[self.pos:self.pos+1], None)
                self.pos += 1
        if not complete:
            self.eof_error = True
        return {'kind': 'array', 'start': start, 'end': self.pos, 'complete': complete}

    def parse_word(self, need=True, bare_color=None, stop_chars=None, command_word=False,
                   assignment_rhs=False, allow_hash_first=False, stop_after_first_group=False):
        self.out.append([])
        try:
            info = self.parse_word_inner(need=need, bare_color=bare_color, stop_chars=stop_chars or set(),
                                         command_word=command_word, assignment_rhs=assignment_rhs,
                                         allow_hash_first=allow_hash_first,
                                         stop_after_first_group=stop_after_first_group)
            buf = self.out.pop()
            return buf, info
        except Bail as e:
            buf = self.out.pop()
            e.pieces = buf + e.pieces
            raise

    def at_word_terminator(self, opts):
        if self.pos >= self.n:
            return True
        c = self.data[self.pos]
        if c in b' \t\n':
            return True
        if c in (opts.get('stop_chars') or set()):
            return True
        if c in b';|':
            return True
        if c == 38:
            return True
        return False

    def parse_expansion_led_group(self, opts):
        # assumes current is a needy expansion (not star/safe) and need=True
        # check pitfall before opening quote for a var at start
        if self.classify_at(self.pos) == 'var':
            self.check_pitfall(self.pos)
        start = self.pos
        self.ins(b'"')
        components = []
        incomplete = False
        closed_by_dquote = False
        while True:
            # parse one expansion component
            info = self.parse_expansion(backtick_convert=True, allow_brace=True, star_convert=False, array_convert=True)
            components.append(info)
            if not info.get('complete', True):
                incomplete = True
                break
            if self.pos >= self.n:
                break
            # next expansion directly?
            if self.classify_expansion_at(self.pos) is not None:
                # pitfall check will happen in parse_var; but if it's a var
                # the opening quote is already emitted correctly.
                continue
            if self.pos < self.n and self.data[self.pos] == 34:
                pieces, dqinfo = self.parse_dquote(merge_open=True)
                self.extend(pieces)
                components.append(dqinfo)
                if dqinfo.get('complete'):
                    closed_by_dquote = True
                else:
                    incomplete = True
                break
            # bare connector?
            if self.at_word_terminator(opts):
                break
            if self.classify_at(self.pos) is not None:
                break
            if self.data[self.pos] == 35 and not opts.get('command_word'):
                break
            if self.data[self.pos:self.pos+2] == b'<<' and not self.starts(b'<<<'):
                break
            # scan bare connector
            end = self.scan_bare_run(self.pos, opts)
            if end <= self.pos:
                break
            after_cls = self.classify_expansion_at(end)
            is_dquote_after = end < self.n and self.data[end] == 34
            if self.is_quotable(self.data[self.pos:end]) and (after_cls is not None or is_dquote_after):
                self.emit(self.data[self.pos:end], C_DQ)
                self.pos = end
                if is_dquote_after and after_cls is None:
                    pieces, dqinfo = self.parse_dquote(merge_open=True)
                    self.extend(pieces)
                    components.append(dqinfo)
                    if dqinfo.get('complete'):
                        closed_by_dquote = True
                    else:
                        incomplete = True
                    break
                # else loop to parse the following expansion
                continue
            break
        if not closed_by_dquote and not incomplete:
            self.ins(b'"')
        return {'kind': 'expansion_led', 'start': start, 'end': self.pos, 'complete': not incomplete, 'components': components}

    def parse_word_inner(self, need, bare_color, stop_chars, command_word, assignment_rhs, allow_hash_first, stop_after_first_group):
        opts = {
            'need': need,
            'bare_color': bare_color,
            'stop_chars': stop_chars,
            'command_word': command_word,
            'assignment_rhs': assignment_rhs,
            'heredoc': True,
            'allow_hash': False,
        }
        word_start = self.pos
        groups = []
        first = True
        stopped_at_lparen = False
        while self.pos < self.n:
            c = self.data[self.pos]
            if c in b' \t\n':
                break
            if c in stop_chars:
                break
            if c in b';|':
                break
            if c == 38:  # &
                break
            if c == 35 and not command_word and not (allow_hash_first and first):
                break
            # heredoc
            if self.data[self.pos:self.pos+2] == b'<<' and not self.starts(b'<<<'):
                if self.try_heredoc():
                    groups.append({'kind': 'heredoc', 'start': word_start, 'end': self.pos, 'complete': not self.eof_error})
                    break
                # else fall through to bare handling
            # array in assignment RHS
            if assignment_rhs and c == 40 and self.pos > 0 and self.data[self.pos-1] == 61:
                g = self.parse_array()
                groups.append(g)
                first = False
                if stop_after_first_group:
                    break
                continue
            # command word stops at '('
            if command_word and c == 40:
                stopped_at_lparen = True
                break
            cls = self.classify_at(self.pos)
            if cls == 'escape':
                g = self.parse_escape()
                groups.append({'kind': 'escape', 'start': g['start'], 'end': g['end'], 'complete': g['complete'], 'components': [g]})
            elif cls == 'ansic':
                g = self.parse_ansic()
                groups.append({'kind': 'quote', 'start': g['start'], 'end': g['end'], 'complete': g['complete'], 'components': [g]})
            elif cls == 'squote':
                g = self.parse_squote()
                groups.append({'kind': 'quote', 'start': g['start'], 'end': g['end'], 'complete': g['complete'], 'components': [g]})
            elif cls == 'dquote':
                pieces, g = self.parse_dquote()
                self.extend(pieces)
                groups.append({'kind': 'quote', 'start': g['start'], 'end': g['end'], 'complete': g['complete'], 'components': [g]})
            elif cls in ('var', 'braced', 'arith', 'cmdsub', 'backtick'):
                if need:
                    safety = self.var_safety(self.pos)
                    if safety == 'safe':
                        g = self.parse_expansion(backtick_convert=False)
                        groups.append({'kind': 'safe_expansion', 'start': g['start'], 'end': g['end'], 'complete': g.get('complete', True), 'components': [g]})
                    elif safety == 'star':
                        # standalone $* -> "$@"
                        st = self.pos
                        self.ins(b'"')
                        g = self.parse_var(star_convert=True)
                        if g.get('complete', True):
                            self.ins(b'"')
                        groups.append({'kind': 'star', 'start': st, 'end': self.pos, 'complete': g.get('complete', True), 'components': [g]})
                    else:
                        g = self.parse_expansion_led_group(opts)
                        groups.append(g)
                else:
                    g = self.parse_expansion(backtick_convert=False)
                    groups.append({'kind': 'expansion', 'start': g['start'], 'end': g['end'], 'complete': g.get('complete', True), 'components': [g]})
            else:
                # bare run
                o2 = dict(opts)
                o2['allow_hash'] = bool(allow_hash_first and first)
                end = self.scan_bare_run(self.pos, o2)
                if end <= self.pos:
                    # Unknown terminator char (e.g. '(' in command word handled above)
                    break
                st = self.pos
                self.emit(self.data[st:end], bare_color)
                self.pos = end
                groups.append({'kind': 'bare', 'start': st, 'end': end, 'complete': True, 'text': self.data[st:end], 'components': [{'kind': 'bare', 'start': st, 'end': end, 'complete': True}]})
            first = False
            if stop_after_first_group:
                break
        return {'kind': 'word', 'start': word_start, 'end': self.pos, 'groups': groups,
                'stopped_at_lparen': stopped_at_lparen, 'raw': self.data[word_start:self.pos]}

    # ----- assignments -----
    def find_subscript_close(self, open_pos):
        i = open_pos + 1
        while i < self.n:
            c = self.data[i]
            if c == 92:
                i += 2
                continue
            if c == 39:
                j = self.data.find(b"'", i + 1)
                if j == -1:
                    return None
                i = j + 1
                continue
            if c == 34:
                j = i + 1
                found = False
                while j < self.n:
                    if self.data[j] == 92:
                        j += 2
                        continue
                    if self.data[j] == 34:
                        found = True
                        break
                    j += 1
                if not found:
                    return None
                i = j + 1
                continue
            if c == 91:  # nested [ disqualifies (observed)
                return None
            if c == 93:  # ]
                # candidate if followed by [, =, +=
                nxt = i + 1
                if nxt < self.n and self.data[nxt] == 91:
                    return i
                if nxt < self.n and self.data[nxt] == 61:
                    return i
                if nxt + 1 < self.n and self.data[nxt] == 43 and self.data[nxt+1] == 61:
                    return i
                # otherwise continue searching (could be ] in content?)
                # But to match a[x]y= failure, if a later ] is the real close it would be found.
                i += 1
                continue
            i += 1
        return None

    def match_assignment(self, pos):
        if pos >= self.n or not is_ident_start(self.data[pos]):
            return None
        i = pos + 1
        while i < self.n and is_ident_char(self.data[i]):
            i += 1
        # optional subscripts
        while i < self.n and self.data[i] == 91:
            close = self.find_subscript_close(i)
            if close is None:
                return None
            i = close + 1
        op_start = i
        if i < self.n and self.data[i] == 43:
            i += 1
        if i < self.n and self.data[i] == 61:
            return (op_start, i + 1)
        return None

    def parse_assignment(self, stop_chars):
        m = self.match_assignment(self.pos)
        if not m:
            return False
        op_start, after_eq = m
        self.emit(self.data[self.pos:op_start], C_NAME)
        self.emit(self.data[op_start:after_eq], None)
        self.pos = after_eq
        # RHS if present
        if self.pos < self.n and self.data[self.pos] not in b' \t\n;&|':
            if self.data[self.pos] not in stop_chars:
                pieces, info = self.parse_word(need=False, bare_color=None, stop_chars=stop_chars,
                                               assignment_rhs=True, allow_hash_first=True)
                self.extend(pieces)
        return True

    # ----- keyword helpers -----
    def keyword_boundary(self, after):
        if after >= self.n:
            return True
        return self.data[after] in b' \t\n;&|()<>'

    def match_keyword(self, words):
        for w in words:
            if self.starts(w):
                after = self.pos + len(w)
                if self.keyword_boundary(after):
                    return w
        return None

    def starts_esac(self, pos):
        if self.data[pos:pos+4] == b'esac':
            after = pos + 4
            if after >= self.n or self.data[after] in b' \t\n;&|()<>':
                return True
        return False

    def is_cond_start(self, pos):
        if self.data[pos:pos+2] != b'[[':
            return False
        if pos + 2 >= self.n:
            return True
        c = self.data[pos+2]
        return c <= 32 or c in b';&|<>()`'

    def is_test_start(self, pos):
        if self.data[pos:pos+2] == b'[ ':
            return pos + 2 < self.n and self.data[pos+2] != 32
        if self.data[pos:pos+5] == b'test ':
            return pos + 5 < self.n and self.data[pos+5] != 32
        return False

    # ----- case -----
    def parse_case(self, parent_stop=None):
        stop_chars = set()
        if parent_stop == 'paren':
            stop_chars = {41}
        elif parent_stop == 'backtick':
            stop_chars = {96}
        self.emit(b'case', C_KW)
        self.pos += 4
        # subject: until 'in' token
        while True:
            if self.pos >= self.n:
                self.eof_error = True
                return
            c = self.data[self.pos]
            if c in b' \t\n':
                j = self.pos
                while j < self.n and self.data[j] in b' \t\n':
                    j += 1
                self.emit(self.data[self.pos:j], C_KW)
                self.pos = j
                continue
            if self.starts(b'in') and (self.pos + 2 >= self.n or self.data[self.pos+2] in b' \t\n;'):
                self.emit(b'in', C_KW)
                self.pos += 2
                break
            if c == 35:
                self.parse_comment()
                continue
            if parent_stop == 'paren' and c == 41:
                self.eof_error = True
                return
            if parent_stop == 'backtick' and c == 96:
                self.eof_error = True
                return
            # one subject word/phrase; separators are part of subject text
            if c in b';&|':
                self.emit(self.data[self.pos:self.pos+1], C_KW)
                self.pos += 1
                continue
            pieces, info = self.parse_word(need=False, bare_color=C_KW, stop_chars=stop_chars)
            if pieces or info['end'] > info['start']:
                self.extend(pieces)
            else:
                self.emit(self.data[self.pos:self.pos+1], C_KW)
                self.pos += 1
        # body: pattern / commands alternation
        while True:
            # pattern state
            pat_result = self.parse_case_pattern(parent_stop, stop_chars)
            if pat_result == 'eof':
                self.eof_error = True
                return
            if pat_result == 'esac':
                self.emit(b'esac', C_KW)
                self.pos += 4
                return
            # pattern_done -> commands
            result = self.parse_normal(stop=parent_stop, case_branch=True)
            if result == 'terminated':
                continue
            if result == 'esac':
                self.ins(b';; ')
                self.emit(b'esac', C_KW)
                self.pos += 4
                return
            # closed parent or eof
            self.eof_error = True
            return

    def parse_case_pattern(self, parent_stop, stop_chars):
        while True:
            if self.pos >= self.n:
                return 'eof'
            c = self.data[self.pos]
            if c in b' \t\n':
                j = self.pos
                while j < self.n and self.data[j] in b' \t\n':
                    j += 1
                self.emit(self.data[self.pos:j], None)
                self.pos = j
                continue
            if self.starts_esac(self.pos):
                return 'esac'
            if c == 41:  # )
                self.emit(b')', None)
                self.pos += 1
                return 'pattern_done'
            if c == 35:
                self.parse_comment()
                continue
            if c in b'|;&':
                self.emit(self.data[self.pos:self.pos+1], None)
                self.pos += 1
                continue
            if parent_stop == 'backtick' and c == 96:
                return 'eof'
            pieces, info = self.parse_word(need=False, bare_color=None, stop_chars={41} | (stop_chars - {41}))
            if pieces or info['end'] > info['start']:
                self.extend(pieces)
            else:
                self.emit(self.data[self.pos:self.pos+1], None)
                self.pos += 1

    # ----- for / select -----
    def parse_for(self, kw):
        # current at kw, and next char is space/tab (caller ensures for special path)
        # returns mode ('pre' or 'arg')
        self.pos += len(kw)
        # consume blanks (space/tab) as part of keyword
        j = self.pos
        while j < self.n and self.data[j] in b' \t':
            j += 1
        self.emit(kw + self.data[self.pos:j], C_KW)
        self.pos = j
        var_consumed = False
        # loop over identifier(s)
        while self.pos < self.n and is_ident_start(self.data[self.pos]):
            # extract ident
            k = self.pos + 1
            while k < self.n and is_ident_char(self.data[k]):
                k += 1
            ident = self.data[self.pos:k]
            if ident == b'in':
                if not var_consumed:
                    # observed weird: treat following as arguments
                    return 'arg'
                break
            self.emit(ident, C_NAME)
            self.pos = k
            var_consumed = True
            # blanks after ident (keyword colored)
            if self.pos < self.n and self.data[self.pos] in b' \t':
                j = self.pos
                while j < self.n and self.data[j] in b' \t':
                    j += 1
                self.emit(self.data[self.pos:j], C_KW)
                self.pos = j
                continue
            else:
                return 'pre'
        if not var_consumed:
            return 'pre'
        # now expect 'in'
        if self.starts(b'in') and (self.pos + 2 >= self.n or not is_ident_char(self.data[self.pos+2])):
            self.emit(b'in', None)
            self.pos += 2
            # special single-variable list pattern?
            if self.try_for_single_var_list():
                return 'pre'
            return 'arg'
        return 'pre'

    def try_for_single_var_list(self):
        # At pos right after 'in'. Lookahead for blanks + $ident + spaces(0x20)* + [;\n]
        i = self.pos
        while i < self.n and self.data[i] in b' \t':
            i += 1
        if i + 1 >= self.n or self.data[i] != 36 or not is_ident_start(self.data[i+1]):
            return False
        j = i + 2
        while j < self.n and is_ident_char(self.data[j]):
            j += 1
        k = j
        while k < self.n and self.data[k] == 32:
            k += 1
        if k >= self.n or self.data[k] not in b';\n':
            return False
        # match: emit leading blanks plain, converted var, trailing spaces keyword
        if i > self.pos:
            self.emit(self.data[self.pos:i], None)
        name = self.data[i+1:j]
        self.ins(b'"')
        self.emit(b'$', C_VAR)
        self.ins(b'{')
        self.emit(name, C_VAR)
        self.ins(b'[@ ]}'.replace(b' ', b'') + b'"')  # [@]}"
        self.pos = j
        if k > j:
            self.emit(self.data[j:k], C_KW)
            self.pos = k
        return True

    # ----- test ([ / test) -----
    def parse_test_command(self, stop_chars):
        # emit token including one trailing space
        if self.starts(b'[ '):
            self.emit(b'[ ', C_CMD)
            self.pos += 2
        else:
            self.emit(b'test ', C_CMD)
            self.pos += 5
        # If nothing follows or terminator, just return arg mode
        if self.pos >= self.n or self.data[self.pos] in b' \t\n;&|':
            return
        if self.data[self.pos] in stop_chars:
            return
        # Capture first word
        first_pieces, first_info = self.parse_word(need=True, bare_color=None, stop_chars=stop_chars)
        first_raw = first_info.get('raw', b'')
        # -n / -z handling
        if first_raw in (b'-n', b'-z'):
            is_n = first_raw == b'-n'
            # exactly one space and a following non-whitespace char
            if self.pos < self.n and self.data[self.pos] == 32 and self.pos + 1 < self.n and self.data[self.pos+1] not in b' \t\n':
                space_pos = self.pos
                self.pos += 1  # consume the single space (held)
                # parse operand first group
                grp_pieces, grp_info = self.parse_word(need=True, bare_color=None, stop_chars=stop_chars,
                                                       stop_after_first_group=True)
                groups = grp_info.get('groups') or []
                first_group_kind = groups[0]['kind'] if groups else 'bare'
                if groups and first_group_kind != 'bare':
                    # delete -n/-z and the space
                    for p in first_pieces:
                        if p[0] == 'o':
                            p[0] = 'd'
                    self.extend(first_pieces)
                    self.dele(b' ', None)
                    self.extend(grp_pieces)
                    self.ins(b' != ""' if is_n else b' = ""')
                    return
                else:
                    self.extend(first_pieces)
                    self.emit(b' ', None)
                    self.extend(grp_pieces)
                    return
            else:
                self.extend(first_pieces)
                return
        # x-comparison handling: need operator and RHS words with exact single spaces
        # Check candidate structure of first word
        def first_word_x_candidate(info):
            groups = info.get('groups') or []
            if len(groups) < 2:
                return False
            g0 = groups[0]
            if g0.get('kind') != 'bare' or g0.get('text') != b'x':
                return False
            # second group must be a non-bare component/group
            if groups[1].get('kind') == 'bare':
                return False
            return True
        if first_word_x_candidate(first_info):
            # need exactly one space, operator word, one space, RHS word starting with x
            save_pos = self.pos
            if self.pos < self.n and self.data[self.pos] == 32 and self.pos + 1 < self.n and self.data[self.pos+1] not in b' \t\n':
                self.pos += 1
                op_pieces, op_info = self.parse_word(need=True, bare_color=None, stop_chars=stop_chars)
                op_raw = op_info.get('raw', b'')
                if op_raw in (b'=', b'!=', b'==') and self.pos < self.n and self.data[self.pos] == 32 and self.pos + 1 < self.n and self.data[self.pos+1] not in b' \t\n':
                    self.pos += 1
                    rhs_pieces, rhs_info = self.parse_word(need=True, bare_color=None, stop_chars=stop_chars)
                    rhs_groups = rhs_info.get('groups') or []
                    rhs_ok = False
                    if rhs_groups and rhs_groups[0].get('kind') == 'bare':
                        txt = rhs_groups[0].get('text', b'')
                        if txt[:1] == b'x':
                            rhs_ok = True
                    if rhs_ok:
                        # modify LHS: delete leading x (first orig piece should be 'x')
                        self._delete_leading_x(first_pieces)
                        self.extend(first_pieces)
                        self.emit(b' ', None)
                        self.extend(op_pieces)
                        self.emit(b' ', None)
                        rhs_empty = self._delete_leading_x(rhs_pieces)
                        self.extend(rhs_pieces)
                        if rhs_empty:
                            self.ins(b'""')
                        return
                    else:
                        # not a match: emit all captured normally
                        self.extend(first_pieces)
                        self.emit(b' ', None)
                        self.extend(op_pieces)
                        self.emit(b' ', None)
                        self.extend(rhs_pieces)
                        return
                else:
                    self.extend(first_pieces)
                    self.emit(b' ', None)
                    self.extend(op_pieces)
                    return
            # fall through: emit first word only
        self.extend(first_pieces)
        return

    def _delete_leading_x(self, pieces):
        # Find first orig piece, split/delete its first 'x'. Return True if nothing (no orig/insert text) remains.
        for idx, p in enumerate(pieces):
            if p[0] == 'o' and p[1]:
                if p[1][:1] == b'x':
                    if len(p[1]) == 1:
                        p[0] = 'd'
                    else:
                        # split into delete x + orig rest
                        rest = [p[0], p[1][1:], p[2]]
                        p[1] = b'x'
                        p[0] = 'd'
                        pieces.insert(idx + 1, rest)
                    break
                else:
                    break
        # empty if no remaining 'o' or 'i' text
        for p in pieces:
            if p[0] in ('o', 'i') and p[1]:
                return False
        return True

    # ----- normal / precommand -----
    def stop_chars_for(self, stop):
        if stop == 'paren':
            return {41}
        if stop == 'backtick':
            return {96}
        return set()

    def handle_precommand(self, stop, case_branch):
        # returns (mode, opened_for)
        stop_chars = self.stop_chars_for(stop)
        c = self.data[self.pos]
        if c in b'<>':
            self.emit(self.data[self.pos:self.pos+1], None)
            self.pos += 1
            return ('pre', False)
        if c == 40:  # (
            if self.starts(b'(('):
                self.parse_arith(dollar=False)
                return ('pre', False)
            self.emit(b'(', None)
            self.pos += 1
            self.parse_normal(stop='paren')
            if self.pos < self.n and self.data[self.pos] == 41:
                self.emit(b')', None)
                self.pos += 1
            else:
                self.eof_error = True
            return ('pre', False)
        if self.is_cond_start(self.pos):
            self.parse_cond()
            return ('pre', False)
        if self.parse_assignment(stop_chars):
            return ('pre', False)
        if self.is_test_start(self.pos):
            self.parse_test_command(stop_chars)
            return ('arg', False)
        # case
        if self.starts(b'case') and self.keyword_boundary(self.pos + 4):
            self.parse_case(parent_stop=stop)
            return ('pre', False)
        # for / select with blank following: special header
        for kw in (b'for', b'select'):
            if self.starts(kw):
                after = self.pos + len(kw)
                if after < self.n and self.data[after] in b' \t':
                    mode = self.parse_for(kw)
                    return (mode, True)
                if self.keyword_boundary(after):
                    self.emit(kw, C_KW)
                    self.pos = after
                    return ('pre', True)
        generic = [b'declare', b'readonly', b'function', b'export', b'local', b'while', b'until',
                    b'then', b'else', b'elif', b'done', b'if', b'fi', b'do', b'{', b'}', b'!']
        kw = self.match_keyword(generic)
        if kw:
            self.emit(kw, C_KW)
            self.pos += len(kw)
            return ('pre', False)
        # ordinary command word
        pieces, info = self.parse_word(need=True, bare_color=C_CMD, stop_chars=stop_chars, command_word=True)
        self.extend(pieces)
        if info.get('stopped_at_lparen'):
            return ('pre', False)
        if not pieces and info['end'] == info['start']:
            # stall guard: consume one char as command
            self.emit(self.data[self.pos:self.pos+1], C_CMD)
            self.pos += 1
        return ('arg', False)

    def parse_normal(self, stop=None, case_branch=False):
        stop_chars = self.stop_chars_for(stop)
        mode = 'pre'
        for_pending = 0
        result = 'eof'
        while self.pos < self.n:
            if stop == 'paren' and self.data[self.pos] == 41:
                result = 'closed'
                break
            if stop == 'backtick' and self.data[self.pos] == 96:
                result = 'closed'
                break
            c = self.data[self.pos]
            if c in b' \t':
                j = self.pos
                while j < self.n and self.data[j] in b' \t':
                    j += 1
                self.emit(self.data[self.pos:j], None)
                self.pos = j
                continue
            if c == 10:
                self.emit(b'\n', None)
                self.pos += 1
                if for_pending > 0:
                    for_pending -= 1
                mode = 'pre'
                continue
            if case_branch and mode == 'pre' and self.starts_esac(self.pos):
                result = 'esac'
                break
            if c == 59:  # ;
                if case_branch and self.starts(b';;'):
                    self.emit(b';;', None)
                    self.pos += 2
                    if for_pending > 0:
                        for_pending -= 1
                    result = 'terminated'
                    # if a for was just closed by this, still terminated
                    break
                self.emit(b';', None)
                self.pos += 1
                if for_pending > 0:
                    for_pending -= 1
                mode = 'pre'
                continue
            if c in b'&|':
                self.emit(self.data[self.pos:self.pos+1], None)
                self.pos += 1
                mode = 'pre'
                continue
            if c == 35:
                self.parse_comment()
                continue
            if mode == 'pre':
                mode, opened = self.handle_precommand(stop, case_branch)
                if opened:
                    for_pending += 1
            else:
                pieces, info = self.parse_word(need=True, bare_color=None, stop_chars=stop_chars)
                if pieces or info['end'] > info['start']:
                    self.extend(pieces)
                else:
                    # stall guard
                    self.emit(self.data[self.pos:self.pos+1], None)
                    self.pos += 1
        else:
            result = 'eof'
        if for_pending > 0:
            self.eof_error = True
        if result == 'eof' and stop is not None:
            self.eof_error = True
        return result


def parse_source(data):
    p = Parser(data)
    try:
        p.parse_normal()
    except Bail as e:
        # flush partial pieces held in popped capture buffers
        while len(p.out) > 1:
            # should not happen (captures pop on Bail), but be safe
            buf = p.out.pop()
            e.pieces = buf + e.pieces
        p.out[0].extend(e.pieces)
        p.out[0].append(['o', b'\n', None])
        return p.out[0], ('unsupported', e)
    except RecursionError:
        # Extremely deep nesting: treat as EOF error rather than crash
        p.eof_error = True
    if p.eof_error:
        p.out[0].append(['o', b'\n', None])
        return p.out[0], ('eof', None)
    return p.out[0], (None, None)


def render(pieces, mode):
    if mode == 'transform':
        out = bytearray()
        for kind, text, color in pieces:
            if kind in ('o', 'i'):
                out.extend(text)
        return bytes(out)
    if mode in ('syntax', 'suggest', 'syntax-suggest'):
        out = bytearray()
        cur = None  # symbolic color or 'insert'/'delete'/None
        for kind, text, color in pieces:
            if mode == 'syntax':
                if kind == 'i':
                    continue
                desired = color
            elif mode == 'suggest':
                if kind == 'i':
                    desired = 'insert'
                elif kind == 'd':
                    desired = 'delete'
                else:
                    desired = None
            else:  # syntax-suggest
                if kind == 'i':
                    desired = 'insert'
                elif kind == 'd':
                    desired = 'delete'
                else:
                    desired = color
            if desired != cur:
                if desired is None:
                    out.extend(RESET)
                else:
                    out.extend(COLOR_CODES[desired])
                cur = desired
            out.extend(text)
        if cur is not None:
            out.extend(RESET)
        return bytes(out)
    # check / replace handled by caller (replace uses transform)
    return b''


def has_changes(pieces):
    return any(k in ('i', 'd') for k, t, c in pieces)


# ----- CLI -----

def write_all(fd, data):
    view = memoryview(data)
    while view:
        n = os.write(fd, view)
        view = view[n:]

def os_error_bytes(e):
    msg = e.strerror or str(e)
    return (msg + f" (os error {e.errno})").encode('utf-8', 'replace')

def panic_write_failed(e):
    # Mimic Rust println panic on stdout/stderr failure for help/version/unknown
    try:
        msg = (f"\nthread 'main' ({os.getpid()}) panicked at library/std/src/io/stdio.rs:1165:9:\n"
               f"failed printing to stdout: {e.strerror or str(e)} (os error {e.errno})\n"
               f"note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        os.write(2, msg.encode())
    except Exception:
        pass
    return 101

class CLI:
    def __init__(self):
        self.mode = 'syntax-suggest'
        self.exit_code = 0

    def write_stdout_for_file(self, data, filename):
        try:
            write_all(1, data)
            return 0
        except OSError as e:
            try:
                write_all(2, filename + b': ' + os_error_bytes(e) + b'\n')
            except Exception:
                pass
            return 1

    def write_stderr(self, data):
        try:
            write_all(2, data)
        except Exception:
            pass

    def diag(self, filename, err, data):
        kind, info = err
        if kind == 'eof':
            self.write_stderr(filename + EOF_MSG)
        elif kind == 'unsupported':
            e = info
            # find line containing e.start
            line_start = data.rfind(b'\n', 0, e.start) + 1
            line_end = data.find(b'\n', e.start)
            if line_end == -1:
                line_end = len(data)
            line = data[line_start:line_end]
            prefix = data[line_start:e.start]
            # count unicode code points (lossy)
            spaces = len(prefix.decode('utf-8', 'replace'))
            out = filename + b': Unsupported syntax: Syntactic pitfall\n' + line + b'\n' + b' ' * spaces + b'^' * e.length + b'\n' + PITFALL_MSG
            self.write_stderr(out)

    def process_file(self, arg):
        # returns: 0 ok, 1 error (continue), 2 check-exit
        is_stdin = (arg == b'')
        filename = arg
        data = None
        if is_stdin:
            try:
                chunks = []
                while True:
                    chunk = os.read(0, 65536)
                    if not chunk:
                        break
                    chunks.append(chunk)
                data = b''.join(chunks)
            except OSError as e:
                self.write_stderr(filename + b': ' + os_error_bytes(e) + b'\n')
                return 1
        else:
            try:
                with open(arg, 'rb') as f:
                    data = f.read()
            except OSError as e:
                if e.errno == 21 and self.mode not in ('check', 'replace'):
                    # Is a directory: original emits a newline to stdout
                    self.write_stdout_for_file(b'\n', arg)
                self.write_stderr(arg + b': ' + os_error_bytes(e) + b'\n')
                return 1
        pieces, err = parse_source(data)
        err_kind = err[0]
        if self.mode == 'check':
            if err_kind is not None or has_changes(pieces):
                return 2
            return 0
        if self.mode == 'replace' and not is_stdin:
            if err_kind is not None:
                self.diag(filename, err, data)
                return 1
            transformed = render(pieces, 'transform')
            if transformed != data:
                try:
                    with open(arg, 'wb') as f:
                        f.write(transformed)
                except OSError as e:
                    self.write_stderr(arg + b': ' + os_error_bytes(e) + b'\n')
                    return 1
            return 0
        mode = 'transform' if self.mode == 'replace' else self.mode
        rendered = render(pieces, mode)
        rc = self.write_stdout_for_file(rendered, arg)
        if err_kind is not None:
            self.diag(filename, err, data)
            return 1
        return rc

    def run(self, argv):
        literal = False
        exit_code = 0
        for arg_str in argv:
            arg = os.fsencode(arg_str)
            if not literal:
                if arg == b'--':
                    literal = True
                    continue
                if arg == b'--suggest':
                    self.mode = 'suggest'
                    continue
                if arg == b'--syntax':
                    self.mode = 'syntax'
                    continue
                if arg == b'--syntax-suggest':
                    self.mode = 'syntax-suggest'
                    continue
                if arg == b'--transform':
                    self.mode = 'transform'
                    continue
                if arg == b'--check':
                    self.mode = 'check'
                    continue
                if arg == b'--replace':
                    self.mode = 'replace'
                    continue
                if arg in (b'-h', b'--help'):
                    try:
                        write_all(1, HELP)
                    except OSError as e:
