python3 - << 'PY'
import os, subprocess, sys
# collect small text files that look like shell scripts from common dirs
cands=[]
for base in ["/etc","/usr/bin","/usr/sbin","/usr/lib","/bin"]:
    for root,dirs,files in os.walk(base):
        dirs[:] = [d for d in dirs if d not in ("node_modules",)]
        for f in files:
            p=os.path.join(root,f)
            try:
                if os.path.getsize(p)>20000: continue
                with open(p,'rb') as fh:
                    head=fh.read(200)
                if head.startswith(b"#!") and (b"sh" in head.split(b"\n")[0]):
                    cands.append(p)
            except Exception: pass
        if len(cands)>60: break
    if len(cands)>60: break
print(len(cands), cands[:20])
bad=0; tested=0
for path in cands[:40]:
    for mode in ["--transform","--syntax"]:
        try:
            a=subprocess.run(["./executable",mode,path],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=3)
            b=subprocess.run([sys.executable,"shellharden.py",mode,path],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=3)
        except subprocess.TimeoutExpired:
            print("TIMEOUT",path,mode); continue
        tested+=1
        if (a.returncode,a.stdout,a.stderr)!=(b.returncode,b.stdout,b.stderr):
            bad+=1
            print("MISMATCH",path,mode,a.returncode,b.returncode)
            # first diff
            for i,(x,y) in enumerate(zip(a.stdout,b.stdout)):
                if x!=y:
                    print(" diff at",i, a.stdout[max(0,i-100):i+150], b"\n---mine---\n", b.stdout[max(0,i-100):i+150]); break
            else:
                if len(a.stdout)!=len(b.stdout): print(" len",len(a.stdout),len(b.stdout), a.stdout[len(b.stdout)-50:len(b.stdout)+150] if len(a.stdout)>len(b.stdout) else b.stdout[len(a.stdout)-50:len(a.stdout)+150])
            if a.stderr!=b.stderr: print(" stderr",a.stderr[:200],b.stderr[:200])
            if bad>=5: break
    if bad>=5: break
print("tested",tested,"bad",bad)
PY
"}

