for base in ["/etc","/usr/bin","/usr/sbin","/usr/lib","/bin","/usr/share"]:
    for root,dirs,files in os.walk(base):
        for f in files:
            p=os.path.join(root,f)
            try:
                if os.path.getsize(p)>30000 or os.path.islink(p): continue
                with open(p,'rb') as fh: head=fh.read(200)
                first=head.split(b"\n")[0]
                if first.startswith(b"#!") and (b"/sh" in first or b"bash" in first or b"dash" in first):
                    cands.append(p)
            except Exception: pass
print("candidates",len(cands),flush=True)
bad=0; tested=0
limit=int(sys.argv[1]) if len(sys.argv)>1 else 80
for path in cands[:limit]:
    for mode in ["--transform","--syntax"]:
        try:
            a=subprocess.run(["./executable",mode,path],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=4)
            b=subprocess.run([sys.executable,"shellharden.py",mode,path],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=4)
        except subprocess.TimeoutExpired:
            print("TIMEOUT",path,mode,flush=True); continue
        tested+=1
        if (a.returncode,a.stdout,a.stderr)!=(b.returncode,b.stdout,b.stderr):
            bad+=1
            print("MISMATCH",path,mode,a.returncode,b.returncode,flush=True)
            for i,(x,y) in enumerate(zip(a.stdout,b.stdout)):
                if x!=y:
                    print(" diff@",i,"\n ref",a.stdout[max(0,i-120):i+180],"\n mine",b.stdout[max(0,i-120):i+180],flush=True); break
            else:
                if len(a.stdout)!=len(b.stdout): print(" outlen",len(a.stdout),len(b.stdout),flush=True)
            if a.stderr!=b.stderr: print(" stderr ref",a.stderr[:300],"mine",b.stderr[:300],flush=True)
            if bad>=6: 
                print("STOP"); sys.exit()
print("tested",tested,"bad",bad)
PY
